<?php
declare(strict_types=1);
$dir=sys_get_temp_dir().'/karfiyat-evidence-'.bin2hex(random_bytes(8));mkdir($dir,0700);
define('DB_PATH',$dir.'/test.sqlite');
register_shutdown_function(static function()use($dir){foreach(glob($dir.'/*') as $f)unlink($f);rmdir($dir);});
require_once __DIR__.'/../includes/functions.php';
$p=['marketplace'=>'trendyol','order_number'=>'001','package_number'=>'123','currency_code'=>'TRY','country_code'=>'TR','status'=>'Delivered','total_price'=>100,'lines'=>[['line_id'=>'5','barcode'=>'0012','quantity'=>2,'price'=>50,'cost_snapshot'=>20]]];
$raw=['id'=>'s1','sellerId'=>123,'barcode'=>'0012','orderNumber'=>'001','shipmentPackageId'=>123,'affiliate'=>'TRENDYOLTR','country'=>'Türkiye','credit'=>100,'debt'=>0,'sellerRevenue'=>81,'commissionAmount'=>19];
$s=['external_id'=>'s1','shipment_package_id'=>'123','order_number'=>'001','query_type'=>'Sale','raw_json'=>json_encode($raw)];
$invoice=['id'=>'F1','sellerId'=>123,'affiliate'=>'TRENDYOLTR','country'=>'Türkiye'];
$c=['invoice_serial'=>'F1','parcel_id'=>'999999','order_number'=>'001','shipment_type'=>'Gönderi Kargo Bedeli','amount'=>12.5,'invoice_raw'=>json_encode($invoice)];
$e=order_evidence([$p],[$s],[$c],[],'123');$tests=[];
$tests['observed components']=$e['sale_commission']===19.0&&$e['sale_revenue']===81.0&&$e['observed_cost']===40.0&&$e['outbound_cargo']===12.5;
$tests['not final profit']=$e['profit']===null&&!$e['issues'];
$tests['commission not deducted twice']=$e['known_subtotal']===28.5;
$tests['single barcode cargo once']=$e['product_components']['0012']['after_cargo']===28.5&&$e['unallocated_product_cargo']===null;
$multi=$p;$multi['lines']=[['line_id'=>'5','barcode'=>'0012','quantity'=>1,'price'=>50,'cost_snapshot'=>20],['line_id'=>'6','barcode'=>'B','quantity'=>1,'price'=>50,'cost_snapshot'=>10]];
$a=$raw;$a['credit']=50;$a['commissionAmount']=9.5;$a['sellerRevenue']=40.5;
$b=array_replace($a,['id'=>'s2','barcode'=>'B']);
$m=order_evidence([$multi],[array_replace($s,['raw_json'=>json_encode($a)]),array_replace($s,['external_id'=>'s2','raw_json'=>json_encode($b)])],[$c],[],'123');
$tests['shared cargo not guessed']=$m['unallocated_product_cargo']===12.5&&$m['product_components']['B']['cargo']===null&&$m['product_components']['B']['before_shared_cargo']===30.5&&$m['product_components']['0012']['after_cargo']===null;
$badRaw=array_replace($raw,['barcode'=>'OTHER']);$badSale=array_replace($s,['raw_json'=>json_encode($badRaw)]);
$badEvidence=order_evidence([$p],[$badSale],[$c],[],'123');
$tests['same package total wrong barcode withheld']=$badEvidence['known_subtotal']===null&&in_array('Satış ekstresi ile barkod tutarı uyuşmuyor',$badEvidence['issues'],true);
$badSale=array_replace($s,['raw_json'=>json_encode(array_replace($raw,['debt'=>1]))]);
$tests['sale debt rejected']=order_evidence([$p],[$badSale],[$c],[],'123')['known_subtotal']===null;
$badCargo=array_replace($c,['shipment_type'=>'İade Kargo Bedeli']);$badEvidence=order_evidence([$p],[$s],[$badCargo],[],'123');
$tests['return cargo not outbound zero']=$badEvidence['outbound_cargo']===null&&$badEvidence['known_subtotal']===null;
$tests['claim prevents subtotal']=order_evidence([$p],[$s],[$c],[['item_id'=>'C1']],'123')['known_subtotal']===null;
$tests['order cargo not package ID']=$e['cargo_rows']===1;
$bad=$s;$bad['shipment_package_id']='999';$e=order_evidence([$p],[$bad],[$c],[],'123');
$tests['wrong package withheld']=$e['unmatched_finance']===1&&$e['sale_commission']===null;
$bad=$raw;$bad['commissionAmount']=21;$badS=$s;$badS['raw_json']=json_encode($bad);
$tests['wrong sale components withheld']=order_evidence([$p],[$badS],[$c],[],'123')['sale_commission']===null;
$e=order_evidence([$p],[$s],[],[],'123');
$tests['no cargo not zero']=$e['outbound_cargo']===null;
$badC=$c;$badC['invoice_raw']=null;
$tests['unknown invoice scope withheld']=order_evidence([$p],[$s],[$badC],[],'123')['outbound_cargo']===null;
$p2=$p;$p2['package_number']='456';$p2['total_price']=50;$p2['lines'][0]['line_id']='6';
$e=order_evidence([$p,$p2],[$s],[$c],[['item_id'=>'x']],'123');
$tests['split order cargo once']=$e['packages']===2&&$e['outbound_cargo']===12.5&&$e['invoice']===150.0&&$e['claim_items']===1&&count($e['issues'])>=2;
$badP=$p;unset($badP['lines'][0]['cost_snapshot']);
$tests['current cost not substituted']=order_evidence([$badP],[$s],[$c],[],'123')['observed_cost']===null;
$badSeller=array_replace($s,['raw_json'=>json_encode(array_replace($raw,['sellerId'=>999]))]);
$tests['foreign seller sale withheld']=order_evidence([$p],[$badSeller],[$c],[],'123')['known_subtotal']===null;
$badInvoice=array_replace($c,['invoice_raw'=>json_encode(array_replace($invoice,['sellerId'=>999]))]);
$tests['foreign seller invoice withheld']=order_evidence([$p],[$s],[$badInvoice],[],'123')['known_subtotal']===null;
$tests['missing binding withheld']=order_evidence([$p],[$s],[$c],[],'')['known_subtotal']===null;
$db=db();
$db->prepare("INSERT INTO integration_bindings(user_id,marketplace,seller_id,stage) VALUES(?,?,?,?)")->execute([2,'trendyol','123',1]);
$malformed=$p;$malformed['order_date']=time();$malformed['lines'][]='invalid';
$overlaid=cost_history_overlay($db,2,[$malformed])[0];
$tests['invalid line not silently discarded']=count($overlaid['lines'])===2&&order_evidence([$overlaid],[$s],[$c],[],'123')['known_subtotal']===null;
$ins=$db->prepare("INSERT INTO orders(user_id,marketplace,order_number,package_number,status,total_price,lines,currency_code,country_code) VALUES(?,?,?,?,?,?,?,?,?)");
foreach([1,2] as $uid)$ins->execute([$uid,'trendyol','001','123','Delivered',100,json_encode($p['lines']),'TRY','TR']);
$ins->execute([1,'trendyol','001','456','Delivered',50,json_encode($p2['lines']),'TRY','TR']);
$db->prepare("INSERT INTO settlements(user_id,marketplace,external_id,order_number,shipment_package_id,query_type,raw_json) VALUES(?,?,?,?,?,?,?)")->execute([2,'trendyol','s1','001','123','Sale',json_encode($raw)]);
$loaded=load_order_evidence($db,1,['001']);
$tests['DB user isolation and all packages']=$loaded['001']['packages']===2&&$loaded['001']['matched_finance']===0;
$loaded=load_order_evidence($db,2,['001']);
$tests['DB exact own records']=$loaded['001']['packages']===1&&$loaded['001']['matched_finance']===1;
$adjustRaw=array_replace($raw,['id'=>'ADJ','credit'=>0,'debt'=>10]);
$adjust=array_replace($s,['external_id'=>'ADJ','query_type'=>'Discount','raw_json'=>json_encode($adjustRaw)]);
$e=order_evidence([$p],[$s,$adjust],[$c],[],'123');
$tests['adjustment balance separately observed']=$e['adjustment_balance']===-10.0&&$e['adjustment_rows']===1&&$e['known_subtotal']===null&&$e['profit']===null;
$tests['adjustment duplicate withheld']=order_adjustment_evidence([$p],[$adjust,$adjust],'123')['balance']===null;
$tests['adjustment wrong barcode withheld']=order_adjustment_evidence([$p],[array_replace($adjust,['raw_json'=>json_encode(array_replace($adjustRaw,['barcode'=>'OTHER']))])],'123')['balance']===null;
$tests['adjustment missing evidence not zero']=order_adjustment_evidence([$p],[$s],'123')['balance']===null;
$tests['adjustment unknown type withheld']=order_adjustment_evidence([$p],[array_replace($adjust,['query_type'=>'UNKNOWN'])],'123')['balance']===null;
foreach($tests as $name=>$ok)echo ($ok?'PASS':'FAIL')." $name\n";
exit(in_array(false,$tests,true)?1:0);
